
local tfw=[==[]==]
local ytg=
(function(...)
local lpn={193,164,68,161,135,29,112,129,118,149,244,75,21,84,232,99,12,65,35,29,42}
local lr=bit32 or bit
local tku=lr.bxor
for np=1,#lpn do lpn[np]=tku(lpn[np],(159*np+171)%256) end
local fhg="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local ezn={}
for kimhv=1,#fhg do ezn[fhg:byte(kimhv)]=kimhv-1 end
local function bhpnb(str)
  local R={} local acc,nb=0,0
  for ztce=1,#str do
    local v=ezn[str:byte(ztce)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function rabm(key,data)
  local S={} for odkaz=0,255 do S[odkaz]=odkaz end
  local j=0
  for gyp=0,255 do
    j=(j+S[gyp]+key[(gyp%#key)+1])%256
    S[gyp],S[j]=S[j],S[gyp]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(tku(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=rabm(lpn,bhpnb(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local zgsk=nf()
return function(big) return zgsk(big) end
end)(...)

return ytg(tfw)
